    "recipe_es": "<p>Hierve el trigo sarraceno hasta que esté desmenuzado.</p><p>Sofríe los champiñones con ajo y aceite de oliva, añade las espinacas y cocina hasta que estén tiernas.</p><p>Mezcla con el trigo sarraceno y termina con limón y sésamo.</p>",
