    "ingredients_fr": "140 g sarrasin, 220 g champignons, 80 g épinards, 1 gousse d'ail, 2 c. à soupe huile d'olive, 1/2 citron, 1 c. à soupe sésame, 1/4 c. à café poivre noir",
    "recipe_fr": "<p>Faites cuire le sarrasin jusqu'à ce qu'il soit émietté.</p><p>Faites revenir les champignons dans l'ail et l'huile d'olive, puis ajoutez les épinards et laissez cuire jusqu'à ce qu'ils soient tendres.</p><p>Mélangez avec le sarrasin et terminez avec du citron et des graines de sésame.</p>",
