    "recipe_ru": "<p>Отварите гречку до состояния рассыпчатой ​​крошки.</p><p>Обжарьте грибы с чесноком и оливковым маслом, добавьте шпинат и варите до мягкости.</p><p>Смешайте с гречкой и добавьте лимон и кунжут.</p>",
